src = open('brute2.py').read()
helper = '''
def over_limit(rq):
    """Independent re-implementation of the published size limits."""
    svcs = rq['services']
    if len(svcs) > 24:
        return 'services'
    if any(len(s) > 64 for s in svcs):
        return 'service scalars'
    if len(rq['rules']) > 32:
        return 'rules'
    if len(rq['queries']) > 256:
        return 'queries'
    tot = 0
    for q in rq['queries']:
        if len(q) > 4096:
            return 'query tokens'
        tot += len(q)
    if tot > 16384:
        return 'total query tokens'
    nodes = [0]
    args_max = [0]
    path_max = [0]
    atoms = set()

    def walk(e):
        nodes[0] += 1
        op = e['op']
        if op in ('match', 'startswith', 'endswith', 'contains'):
            path_max[0] = max(path_max[0], len(e['path']))
            atoms.add((op, tuple(e['path'])))
        elif op == 'not':
            walk(e['arg'])
        elif op in ('and', 'or'):
            args_max[0] = max(args_max[0], len(e['args']))
            for a in e['args']:
                walk(a)
    for r in rq['rules']:
        walk(r['when'])
    if nodes[0] > 256:
        return 'nodes %d' % nodes[0]
    if args_max[0] > 32:
        return 'args'
    if path_max[0] > 16:
        return 'atom path'
    if len(atoms) > 10:
        return 'atoms %d' % len(atoms)
    if len(json.dumps(rq, ensure_ascii=False).encode('utf-8')) > 1048576:
        return 'line bytes'
    return None


'''
